use crate::aap::caps::kb_read;
use crate::aap::caps::tool_llm::{self, Reply};

struct Node;

const SYSTEM: &str =
    "You are a customer-support agent. Answer the user's question using the \
     supplied knowledge. If you need to look something up in the knowledge base, \
     request the `lookup` tool; otherwise answer directly.";

/// Upper bound on tool-orchestration rounds, so a model that keeps asking for
/// tools can never spin the node forever.
const MAX_ROUNDS: u32 = 4;

impl Guest for Node {
    fn run(ctx: ConversationContext) -> ResponseResult {
        // `requires len(question) <= 512` holds of every input, so the question
        // is already bounded when it reaches us; we build the prompt directly.
        let mut prompt = String::new();
        prompt.push_str("Intent: ");
        prompt.push_str(intent_label(ctx.intent));
        prompt.push('\n');
        prompt.push_str("Question: ");
        prompt.push_str(&ctx.question);

        if !ctx.knowledge.is_empty() {
            prompt.push_str("\n\nKnowledge supplied with the query:\n");
            for k in &ctx.knowledge {
                prompt.push_str("- ");
                prompt.push_str(k);
                prompt.push('\n');
            }
        }

        let mut rounds: u32 = 0;
        loop {
            match tool_llm::generate(SYSTEM, &prompt) {
                Reply::Text(text) => {
                    return ResponseResult::Ok(AgentResponse { text });
                }
                Reply::Call(req) => {
                    if rounds >= MAX_ROUNDS {
                        return ResponseResult::Error(LlmError {
                            message: "tool-orchestration round limit exceeded"
                                .to_string(),
                        });
                    }
                    rounds += 1;

                    // The only tool in this node's scope is the knowledge-base
                    // lookup. Anything else is not authority we hold; we refuse
                    // it in-band and let the model answer without it.
                    if req.tool == "lookup" {
                        let results = kb_read::lookup(&req.query);
                        prompt.push_str("\n\nTool `lookup` results for \"");
                        prompt.push_str(&req.query);
                        prompt.push_str("\":\n");
                        if results.is_empty() {
                            prompt.push_str("(no matches)\n");
                        } else {
                            for r in &results {
                                prompt.push_str("- ");
                                prompt.push_str(r);
                                prompt.push('\n');
                            }
                        }
                    } else {
                        prompt.push_str("\n\nTool `");
                        prompt.push_str(&req.tool);
                        prompt.push_str("` is not available to this node; \
                             answer using what you already have.\n");
                    }
                }
            }
        }
    }
}

fn intent_label(intent: Intent) -> &'static str {
    match intent {
        Intent::BillingQuestion => "billing-question",
        Intent::TechnicalSupport => "technical-support",
        Intent::AccountChange => "account-change",
        Intent::GeneralInquiry => "general-inquiry",
        Intent::Unknown => "unknown",
    }
}

export!(Node);
